def createTask(content, description=None, project_id=None, section_id=None, parent_id=None, order=None, priority=None, due_string=None, due_date=None, due_datetime=None, due_lang=None, assignee_id=None, labels=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0047000" if __import__("os").path.isdir("./environment_mix/0047000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ds = _load("dataset.json")
    if not isinstance(ds, dict):
        ds = {}
    if "records" not in ds or not isinstance(ds.get("records"), list):
        ds["records"] = []
    if "_audit" not in ds or not isinstance(ds.get("_audit"), list):
        ds["_audit"] = []
    if "_counters" not in ds or not isinstance(ds.get("_counters"), dict):
        ds["_counters"] = {"requests_total": 0, "requests_by_tool": {}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ds["_audit"].append({
            "id": str(int(time.time() * 1000)),
            "tool": "createTask",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms,
            "error_code": error_code
        })
        ds["_counters"]["requests_total"] = int(ds["_counters"].get("requests_total", 0)) + 1
        rbt = ds["_counters"].get("requests_by_tool", {})
        rbt["createTask"] = int(rbt.get("createTask", 0)) + 1
        ds["_counters"]["requests_by_tool"] = rbt

    # Simple rate-limit based on audit log: 120 requests per rolling 60 seconds.
    window_s = 60
    limit = 120
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    recent = 0
    for ev in ds["_audit"]:
        ts = ev.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
    if recent >= limit:
        _log("error", "RATE_LIMIT")
        _save("dataset.json", ds)
        return _err("RATE_LIMIT", "Too many requests. Please try again later.")

    # Validate inputs
    if not isinstance(content, str) or not content.strip():
        _log("error", "VALIDATION_ERROR")
        _save("dataset.json", ds)
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string.", field="content")

    num_pat = re.compile(r"^[0-9]+$")
    for field_name, v in (("project_id", project_id), ("section_id", section_id), ("parent_id", parent_id), ("assignee_id", assignee_id)):
        if v is not None:
            if not isinstance(v, str) or not num_pat.match(v):
                _log("error", "VALIDATION_ERROR")
                _save("dataset.json", ds)
                return _err("VALIDATION_ERROR", f"{field_name} must be a numeric string.", field=field_name)

    if order is not None:
        if not isinstance(order, int) or order < 1:
            _log("error", "VALIDATION_ERROR")
            _save("dataset.json", ds)
            return _err("VALIDATION_ERROR", "order must be an integer >= 1.", field="order")
    if priority is not None:
        if not isinstance(priority, int) or priority not in (1, 2, 3, 4):
            _log("error", "VALIDATION_ERROR")
            _save("dataset.json", ds)
            return _err("VALIDATION_ERROR", "priority must be one of 1,2,3,4.", field="priority")

    if due_date is not None:
        if not isinstance(due_date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", due_date):
            _log("error", "VALIDATION_ERROR")
            _save("dataset.json", ds)
            return _err("VALIDATION_ERROR", "due_date must be in YYYY-MM-DD format.", field="due_date")

    if labels is not None:
        if not isinstance(labels, list) or any((not isinstance(x, str)) for x in labels):
            _log("error", "VALIDATION_ERROR")
            _save("dataset.json", ds)
            return _err("VALIDATION_ERROR", "labels must be an array of strings.", field="labels")

    # Enforce references if provided: since this datastore only has dataset.records, treat numeric ids as referencing existing record ids.
    existing_ids = {str(r.get("id")) for r in ds["records"] if isinstance(r, dict) and r.get("id") is not None}
    for ref_name, v in (("project_id", project_id), ("section_id", section_id), ("parent_id", parent_id), ("assignee_id", assignee_id)):
        if v is not None and v not in existing_ids:
            _log("error", "NOT_FOUND")
            _save("dataset.json", ds)
            return _err("NOT_FOUND", f"Referenced {ref_name} does not exist or is not accessible.", field=ref_name, id=v)

    # Generate a unique numeric string id
    used_numeric = set()
    for r in ds["records"]:
        if isinstance(r, dict):
            rid = r.get("id")
            if isinstance(rid, str) and num_pat.match(rid):
                used_numeric.add(int(rid))
    new_id_int = (max(used_numeric) + 1) if used_numeric else 1
    new_id = str(new_id_int)

    task = {
        "id": new_id,
        "name": "Todoist Task",          # schema requires name, but tool doesn't provide; set a service-derived label
        "title": content,
        "status": "active",
        "created_at": now,
        "description": description,
        "project_id": project_id,
        "section_id": section_id,
        "parent_id": parent_id,
        "order": order,
        "priority": priority,
        "due_string": due_string,
        "due_date": due_date,
        "due_datetime": due_datetime,
        "due_lang": due_lang,
        "assignee_id": assignee_id,
        "labels": labels[:] if isinstance(labels, list) else None,
        "type": "task"
    }
    # Remove None keys to mimic typical API storage
    task = {k: v for k, v in task.items() if v is not None}

    ds["records"].append(task)
    # refresh meta if present/desired
    meta = ds.get("_meta")
    if not isinstance(meta, dict):
        meta = {}
    meta["record_count"] = len(ds["records"])
    ds["_meta"] = meta

    _log("success", None)
    _save("dataset.json", ds)
    return {"task": task}

