        rbt["completeTask"] = int(rbt.get("completeTask", 0)) + 1
        ds["_counters"]["requests_by_tool"] = rbt

    # rate limit
    window_s = 60
    limit = 120
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    recent = 0
    for ev in ds["_audit"]:
        ts = ev.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
    if recent >= limit:
        _log("error", "RATE_LIMIT")
        _save("dataset.json", ds)
        return _err("RATE_LIMIT", "Too many requests. Please try again later.")

    if not isinstance(task_id, str) or not re.match(r"^[0-9]+$", task_id):
        _log("error", "VALIDATION_ERROR")
        _save("dataset.json", ds)
        return _err("VALIDATION_ERROR", "task_id must be a numeric string.", field="task_id")

    idx = None
    for i, r in enumerate(ds["records"]):
        if isinstance(r, dict) and str(r.get("id")) == task_id and r.get("type") in (None, "task"):
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        _save("dataset.json", ds)
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    task = ds["records"][idx]
    status = task.get("status")
    if status == "completed":
        _log("error", "INVALID_TRANSITION")
        _save("dataset.json", ds)
        return _err("INVALID_TRANSITION", "Task is already completed.", task_id=task_id)
    if status in ("archived", "draft", "pending"):
        _log("error", "INVALID_TRANSITION")
        _save("dataset.json", ds)
        return _err("INVALID_TRANSITION", f"Task in state '{status}' cannot be completed.", task_id=task_id)

    task = dict(task)
    task["status"] = "completed"
    task["completed_at"] = now
    ds["records"][idx] = task

    _log("success", None)
    _save("dataset.json", ds)
    return {"task": task}

