        meta = {}
    meta["record_count"] = len(ds["records"])
    ds["_meta"] = meta

    _log("success", None)
    _save("dataset.json", ds)
    return {"label": label}

def deleteLabel(label_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0047000" if __import__("os").path.isdir("./environment_mix/0047000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ds = _load("dataset.json")
    if not isinstance(ds, dict):
        ds = {}
    if "records" not in ds or not isinstance(ds.get("records"), list):
        ds["records"] = []
    if "_audit" not in ds or not isinstance(ds.get("_audit"), list):
        ds["_audit"] = []
    if "_counters" not in ds or not isinstance(ds.get("_counters"), dict):
        ds["_counters"] = {"requests_total": 0, "requests_by_tool": {}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ds["_audit"].append({
            "id": str(int(time.time() * 1000)),
            "tool": "deleteLabel",
            "timestamp": now,
            "status": status,
            "latency_ms": latency_ms,
            "error_code": error_code
        })
        ds["_counters"]["requests_total"] = int(ds["_counters"].get("requests_total", 0)) + 1
        rbt = ds["_counters"].get("requests_by_tool", {})
        rbt["deleteLabel"] = int(rbt.get("deleteLabel", 0)) + 1
        ds["_counters"]["requests_by_tool"] = rbt

    window_s = 60
    limit = 120
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
    recent = 0
    for ev in ds["_audit"]:
        ts = ev.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
    if recent >= limit:
        _log("error", "RATE_LIMIT")
        _save("dataset.json", ds)
        return _err("RATE_LIMIT", "Too many requests. Please try again later.")

    if not isinstance(label_id, str) or not re.match(r"^[0-9]+$", label_id):
        _log("error", "VALIDATION_ERROR")
        _save("dataset.json", ds)
        return _err("VALIDATION_ERROR", "label_id must be a numeric string.", field="label_id")

    idx = None
    for i, r in enumerate(ds["records"]):
        if isinstance(r, dict) and str(r.get("id")) == label_id and r.get("type") == "label":
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        _save("dataset.json", ds)
        return _err("NOT_FOUND", "Label not found.", label_id=label_id)

    deleted = ds["records"].pop(idx)

    meta = ds.get("_meta")
    if not isinstance(meta, dict):
        meta = {}
    meta["record_count"] = len(ds["records"])
    ds["_meta"] = meta

    _log("success", None)
    _save("dataset.json", ds)
    return {"deleted": True, "label": deleted}

